import{_ as a,a0 as o,w as l,s as d,ao as r,I as p,x as e,a1 as s,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何讓 Ping 的輸出更簡單易讀 | LCTT x X-CMD","titleTemplate":false,"description":"如何讓 Ping 的輸出更簡單易讀 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何讓 Ping 的輸出更簡單易讀 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何讓 Ping 的輸出更簡單易讀 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20180924 Make The Output Of Ping Command Prettier And Easier To Read","title":"如何讓 Ping 的輸出更簡單易讀","tag":"201809","desc":""},"relativePath":"201809/20180924 Make The Output Of Ping Command Prettier And Easier To Read.md","filePath":"[post].md"}'),g={name:"201809/20180924 Make The Output Of Ping Command Prettier And Easier To Read.md"};function c(h,i,u,k,b,m){const t=o("Link");return l(),d("div",null,[i[15]||(i[15]=r('<h1 id="如何讓-ping-的輸出更簡單易讀" tabindex="-1">如何讓 Ping 的輸出更簡單易讀 <a class="header-anchor" href="#如何讓-ping-的輸出更簡單易讀" aria-label="Permalink to “如何讓 Ping 的輸出更簡單易讀”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/prettyping-720x340.png" alt=""></p><p>眾所周知，<code>ping</code> 命令可以用來檢查目標主機是否可達。使用 <code>ping</code> 命令的時候，會發送一個 ICMP Echo 請求，通過目標主機的響應與否來確定目標主機的狀態。如果你經常使用 <code>ping</code> 命令，你可以嘗試一下 <code>prettyping</code>。Prettyping 只是將一個標準的 ping 工具增加了一層封裝，在運行標準 <code>ping</code> 命令的同時添加了顏色和 unicode 字符解析輸出，所以它的輸出更漂亮緊湊、清晰易讀。它是用 <code>bash</code> 和 <code>awk</code> 編寫的自由開源工具，支持大部分類 Unix 操作系統，包括 GNU/Linux、FreeBSD 和 Mac OS X。Prettyping 除了美化 <code>ping</code> 命令的輸出，還有很多值得注意的功能。</p><ul><li>檢測丟失的數據包並在輸出中標記出來。</li><li>顯示實時數據。每次收到響應後，都會更新統計數據，而對於普通 <code>ping</code> 命令，只會在執行結束後統計。</li><li>可以靈活處理“未知信息”（例如錯誤信息），而不搞亂輸出結果。</li><li>能夠避免輸出重複的信息。</li><li>兼容常用的 <code>ping</code> 工具命令參數。</li><li>能夠由普通用户執行。</li><li>可以將輸出重定向到文件中。</li><li>不需要安裝，只需要下載二進制文件，賦予可執行權限即可執行。</li><li>快速且輕巧。</li><li>輸出結果清晰直觀。</li></ul><h3 id="安裝-prettyping" tabindex="-1">安裝 Prettyping <a class="header-anchor" href="#安裝-prettyping" aria-label="Permalink to “安裝 Prettyping”">​</a></h3><p>如上所述，Prettyping 是一個綠色軟件，不需要任何安裝，只要使用以下命令下載 Prettyping 二進制文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -O https://raw.githubusercontent.com/denilsonsa/prettyping/master/prettyping</span></span></code></pre></div><p>將二進制文件放置到 <code>$PATH</code>（例如 <code>/usr/local/bin</code>）中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mv prettyping /usr/local/bin</span></span></code></pre></div><p>然後對其賦予可執行權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod +x /usr/local/bin/prettyping</span></span></code></pre></div><p>就可以使用了。</p><h3 id="讓-ping-的輸出清晰易讀" tabindex="-1">讓 ping 的輸出清晰易讀 <a class="header-anchor" href="#讓-ping-的輸出清晰易讀" aria-label="Permalink to “讓 ping 的輸出清晰易讀”">​</a></h3><p>安裝完成後，通過 <code>prettyping</code> 來 ping 任何主機或 IP 地址，就可以以圖形方式查看輸出。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ prettyping ostechnix.com</span></span></code></pre></div><p>輸出效果大概會是這樣：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/prettyping-in-action.gif" alt=""></p><p>如果你不帶任何參數執行 <code>prettyping</code>，它就會一直運行直到被 <code>ctrl + c</code> 中斷。</p><p>由於 Prettyping 只是一個對普通 <code>ping</code> 命令的封裝，所以常用的 ping 參數也是有效的。例如使用 <code>-c 5</code> 來指定 ping 一台主機的 5 次：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ prettyping -c 5 ostechnix.com</span></span></code></pre></div><p>Prettyping 默認會使用彩色輸出，如果你不喜歡彩色的輸出，可以加上 <code>--nocolor</code> 參數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ prettyping --nocolor ostechnix.com</span></span></code></pre></div><p>同樣的，也可以用 <code>--nomulticolor</code> 參數禁用多顏色支持：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ prettyping --nomulticolor ostechnix.com</span></span></code></pre></div><p>使用 <code>--nounicode</code> 參數禁用 unicode 字符：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/09/prettyping-without-unicode-support.png" alt=""></p><p>如果你的終端不支持 UTF-8，或者無法修復系統中的 unicode 字體，只需要加上 <code>--nounicode</code> 參數就能輕鬆解決。</p><p>Prettyping 支持將輸出的內容重定向到文件中，例如執行以下這個命令會將 <code>prettyping ostechnix.com</code> 的輸出重定向到 <code>ostechnix.txt</code> 中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ prettyping ostechnix.com | tee ostechnix.txt</span></span></code></pre></div><p>Prettyping 還有很多選項幫助你完成各種任務，例如：</p><ul><li>啓用/禁用延時圖例（默認啓用）</li><li>強制按照終端的格式輸出（默認自動）</li><li>在統計數據中統計最後的 n 次 ping（默認 60 次）</li><li>覆蓋對終端尺寸的自動檢測</li><li>指定 awk 解釋器路徑（默認：<code>awk</code>）</li><li>指定 ping 工具路徑（默認：<code>ping</code>）</li></ul><p>查看幫助文檔可以瞭解更多：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ prettyping --help</span></span></code></pre></div><p>儘管 Prettyping 沒有添加任何額外功能，但我個人喜歡它的這些優點：</p><ul><li>實時統計 —— 可以隨時查看所有實時統計信息，標準 <code>ping</code> 命令只會在命令執行結束後才顯示統計信息。</li><li>緊湊的顯示 —— 可以在終端看到更長的時間跨度。</li><li>檢測丟失的數據包並顯示出來。</li></ul><p>如果你一直在尋找可視化顯示 <code>ping</code> 命令輸出的工具，那麼 Prettyping 肯定會有所幫助。嘗試一下，你不會失望的。</p><hr>',37)),p("p",null,[i[1]||(i[1]=e("via: ",-1)),s(t,{href:"https://www.ostechnix.com/prettyping-make-the-output-of-ping-command-prettier-and-easier-to-read/"},{default:n(()=>[...i[0]||(i[0]=[e("https://www.ostechnix.com/prettyping-make-the-output-of-ping-command-prettier-and-easier-to-read/",-1)])]),_:1})]),p("p",null,[i[6]||(i[6]=e("作者：",-1)),s(t,{href:"https://www.ostechnix.com/author/sk/"},{default:n(()=>[...i[2]||(i[2]=[e("SK",-1)])]),_:1}),i[7]||(i[7]=e(" 選題：",-1)),s(t,{href:"https://github.com/lujun9972"},{default:n(()=>[...i[3]||(i[3]=[e("lujun9972",-1)])]),_:1}),i[8]||(i[8]=e(" 譯者：",-1)),s(t,{href:"https://github.com/HankChow"},{default:n(()=>[...i[4]||(i[4]=[e("HankChow",-1)])]),_:1}),i[9]||(i[9]=e(" 校對：",-1)),s(t,{href:"https://github.com/wxy"},{default:n(()=>[...i[5]||(i[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[i[12]||(i[12]=e("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...i[10]||(i[10]=[e("LCTT",-1)])]),_:1}),i[13]||(i[13]=e(" 原創編譯，",-1)),s(t,{href:"https://linux.cn/"},{default:n(()=>[...i[11]||(i[11]=[e("Linux中國",-1)])]),_:1}),i[14]||(i[14]=e(" 榮譽推出",-1))])])}const C=a(g,[["render",c]]);export{x as __pageData,C as default};
